function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Character · CORE</title><link rel="stylesheet" href="<?=$base?>/player.css"><script src="https://cdn.babylonjs.com/babylon.js"></script></head><body><header class="topbar"><a class="brand" href="<?=$base?>/selection.php"><span class="brand-mark">C</span><span>CORE <small>CHARACTER CREATION</small></span></a><span class="build-tag"><?=h($releaseVersion)?></span></header><main class="player-flow"><section class="panel creation-screen"><div class="eyebrow">STEP 1 · CHARACTER IDENTITY</div><h1>Create your <span>character.</span></h1><p>This character is saved independently. You can create and assign a universe in the next step.</p><div class="character-creation-layout"><aside class="character-preview-panel"><div class="eyebrow">LIVE 3D PREVIEW</div><h2>Character silhouette</h2><p class="creation-intro">A procedural Babylon.js primitive preview. This is a visual placeholder; saved character data remains independent of the model.</p><div class="character-preview-canvas-wrap"><canvas id="characterPreviewCanvas" aria-label="Interactive 3D character preview"></canvas><div id="characterPreviewStatus" class="preview-status" role="status">Initializing 3D preview…</div></div><div class="preview-controls"><label for="previewColor">Preview color</label><input id="previewColor" type="color" value="#61d8e8"><small>Drag to orbit · scroll to zoom</small></div></aside><div class="character-form-column"><form method="post" action="<?=$base?>/player-action.php" class="creation-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['core_csrf']??=bin2hex(random_bytes(32)))?>"><input type="hidden" name="action" value="create_character"><label>Character name</label><input name="name" required minlength="2" maxlength="40" autocomplete="off"><div class="creation-grid"><div><label>Role</label><select name="role_id" required><?php foreach(($options['roles']??[]) as $r): ?><option value="<?=h($r['id'])?>"><?=h($r['label'])?></option><?php endforeach; ?></select></div><div><label>Species</label><select name="species_id" required><?php foreach(($options['species']??[]) as $sp): ?><option value="<?=h($sp['id'])?>"><?=h($sp['label'])?></option><?php endforeach; ?></select></div></div><h2>Abilities</h2><div class="attribute-grid"><?php foreach(($options['attributes']??[]) as $a): ?><div><label><?=h($a['label'])?></label><input type="number" name="attributes[<?=h($a['id'])?>]" min="<?=h($a['minimum']??1)?>" max="<?=h($a['maximum']??30)?>" value="<?=h($a['default']??10)?>" required></div><?php endforeach; ?></div><div class="creation-actions"><a class="button-secondary" href="<?=$base?>/selection.php">Cancel</a><button type="submit">Save character</button></div></form></div></div></section></main><script src="<?=$base?>/character-preview.js"></script></body></html>